package dev.martianzoo.pets

import dev.martianzoo.pets.api.Exceptions.PetSyntaxException
import dev.martianzoo.pets.ast.ClassName
import dev.martianzoo.pets.ast.ClassName.Companion.cn
import dev.martianzoo.pets.ast.Expression
import dev.martianzoo.pets.ast.PetNode
import dev.martianzoo.pets.ast.TransformNode
import dev.martianzoo.pets.data.ClassDeclaration

// TODO: Contract this temporary tfm-canon seam.
/**
 * Lowers parsed owner-local Classes to ordinary, stably named Class declarations, as defined by
 * [section 12](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/pets-language-spec.md#12-owner-local-classes).
 * A card often needs a class of its own — one required action, one special tile, one remote area —
 * that no other card will ever mention; rather than force a name, the definition declares the class
 * where it is used ([rule
 * L12-1](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/pets-language-spec.md#12-owner-local-classes))
 * and the name is derived from [owner] ([rule
 * L12-2](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/pets-language-spec.md#12-owner-local-classes)).
 *
 * This is source-level lowering: it happens while the declaration file is parsed, so the type
 * system never sees anything but ordinary declarations. Naming a base class with no local body is
 * still just that base class ([rule
 * L12-8](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/pets-language-spec.md#12-owner-local-classes)).
 * A local declaration inside a transform block is rejected rather than extracted without its mark
 * ([rule
 * L8-6](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/pets-language-spec.md#8-transform-blocks)).
 */
public class DerivedClassLowerer(private val owner: ClassName) : PetTransformer() {
  private val declarationsByBase = linkedMapOf<ClassName, ClassDeclaration>()

  internal fun lowerDeclaration(declaration: ClassDeclaration): List<ClassDeclaration> {
    val ordinary = Parsing.completeDeclaration(Parsing.transformDeclaration(declaration, this))
    return listOf(ordinary) +
        declarationsByBase.values.map {
          Parsing.completeDeclaration(it, generated = true)
        }
  }

  override fun transformNode(node: PetNode): PetNode {
    if (node is TransformNode<*> && node.extract().containsDerivedClass()) {
      throw PetSyntaxException(
          "transform blocks cannot contain owner-local class declarations; declare the class separately",
          sourceLocation = node.sourceLocation,
      )
    }
    if (node !is Expression) return transformChildren(node)
    val body = (node as? SourceExpression)?.body ?: return transformChildren(node)

    // Rule L12-2: the generated name is the owner's name, an underscore, and the base class name,
    // so `SpecialTile<> {}` on MiningRights becomes `MiningRights_SpecialTile`.
    val base = node.className
    val generated = cn("${owner}_$base").also { it.sourceLocation = node.sourceLocation }
    val bodyNodes = body.asDerivedDeclaration(generated, base.expression).allNodes
    // Rule L12-5: owner-local Classes do not nest, in the body or in an argument of the occurrence.
    if (
        node.childNodes().any { it.containsDerivedClass() } ||
            bodyNodes.any { it.containsDerivedClass() }
    ) {
      throw PetSyntaxException(
          "owner-local classes cannot contain owner-local classes",
          sourceLocation = node.sourceLocation,
      )
    }
    // Rule L12-6: one owner declares at most one unnamed local class per base name, so the derived
    // name stays stable rather than depending on source order.
    if (base in declarationsByBase) {
      throw PetSyntaxException(
          "owner `$owner` declares more than one unnamed derived `$base` class",
          sourceLocation = node.sourceLocation,
      )
    }

    // Rule L12-3: arguments specialize both the occurrence and the generated supertype, while
    // refinements constrain only the occurrence — a refined type cannot be a supertype (L11-4).
    val loweredArguments = node.arguments.map(::transformExpression)
    val loweredRefinement = node.refinement?.let(::transformRefinement)
    val declarationContext = Transforming.replaceThisExpressionsWith(owner.expression)
    val supertype =
        Expression(
            className = base,
            arguments =
                loweredArguments
                    .map(declarationContext::transformExpression)
                    .map(::withoutRefinements),
        )
    val declaration = body.asDerivedDeclaration(generated, supertype)
    declarationsByBase[base] = Parsing.transformDeclaration(declaration, this)
    return Expression(
        generated,
        loweredArguments,
        loweredRefinement,
        node.argumentsSpecified,
    )
  }

  private fun withoutRefinements(expression: Expression): Expression =
      expression.copy(
          arguments = expression.arguments.map(::withoutRefinements),
          refinement = null,
      )

  private fun PetNode.containsDerivedClass(): Boolean =
      descendantsOfType<Expression>().any { it is SourceExpression }
}
