/**
 * Incrementally compiles supplied declarations into the single master universe specified by
 * [rules T1-1 and T1-6](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
 *
 * Name lookup and resolution are available while loading. [loadEverything] completes and freezes a
 * master universe. A game table freezes its combined structural namespace before computing the
 * premise's inclusion closure, so every enumeration used by that closure has a stable namespace.
 * Compilation rejects inheritance deeper than 128 classes (including `Component`) or more than 128
 * simultaneous class constructions with [ResourceLimitException], before recursive class processing
 * exhausts the stack.
 */
public class ClassLoader
private constructor(
    private val declarations: Map<ClassName, ClassDeclaration>,
    internal override val transformHandlerFactories: Map<String, (ClassTable) -> TransformHandler>,
    private val validateDeclaration: (ClassDeclaration) -> Unit,
    private val masterSource: ClassTable?,
    private val checkAvailability: (ClassName, ClassName?) -> Unit = { _, _ -> },
    private val exactCount: (Expression, ClassTable) -> Int? = { _, _ -> null },
    private val selectedModuleCount: (Expression, ClassTable) -> Int? = { _, _ -> null },
) : ClassTable() {
  /**
   * Begins compiling a master universe from [declarations]. Call [loadEverything] before
   * enumeration. By default this compiles Pets declarations alone. [validateDeclaration] applies
   * additional declaration checks supplied by Catalog assembly.
   */
  public constructor(
      declarations: Map<ClassName, ClassDeclaration>,
      transformHandlerFactories: Map<String, (ClassTable) -> TransformHandler> = emptyMap(),
      validateDeclaration: (ClassDeclaration) -> Unit = {},
  ) : this(
      declarations,
      transformHandlerFactories,
      validateDeclaration,
      null,
  )

  internal override val masterTable: ClassTable = masterSource ?: this

  private val knownClassNames: Set<ClassName> =
      masterSource?.allClassNames.orEmpty() + declarations.keys

  private val cache = mutableMapOf<Expression, GroundType>()

  /**
   * The required `Component` root specified by
   * [rule T1-4](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  public override val componentClass: Class =
      masterSource?.componentClass
          ?: Class(
              knownDeclaration(COMPONENT).also(validateDeclaration),
              this,
              directSuperclasses = emptyList(),
          )

  /**
   * The required `Class` class specified by
   * [rule T1-5](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  public override val classClass: Class =
      masterSource?.classClass
          ?: Class(
              knownDeclaration(CLASS).also(validateDeclaration),
              this,
              directSuperclasses = listOf(componentClass),
          )

  private val loadedClasses =
      mutableMapOf<ClassName, Class?>(COMPONENT to componentClass, CLASS to classClass)
  private val includedClassNames = linkedSetOf(COMPONENT, CLASS)
  private var premiseEffects: Map<Class, List<Effect>>? = null

  /**
   * Returns the already loaded class named [name], or null; exact-name lookup during loading
   * follows
   * [rules T1-6 and T1-7](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  override fun findClass(name: ClassName): Class? {
    return if (name in loadedClasses) {
      loadedClasses[name] ?: throw inheritanceCycle(name)
    } else {
      masterSource?.findClass(name)
    }
  }

  /**
   * Returns declaration effects in a master loader and premise-specialized effects in a premise
   * loader. [klass] must belong to this loader's universe; a premise loader also requires the class
   * to be included and its effect compilation to be complete.
   */
  public override fun effects(klass: Class): List<Effect> {
    require(accepts(klass.classTable)) { "`$klass` belongs to a different Catalog" }
    if (masterSource == null) return klass.declaration.effects
    val effects = checkNotNull(premiseEffects) { "premise effects are not complete" }
    return requireNotNull(effects[klass]) { "`$klass` is not included in this premise" }
  }

  /**
   * Resolves [expression] with strict exact names under
   * [rules T1-3 and T1-7](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   *
   * @throws ExpressionException if [expression] is invalid in this universe.
   */
  override fun resolve(expression: Expression): GroundType {
    val expanded = expression.expandClassLiteralTypeVariableName()
    if (expanded !== expression && expanded != expression) return resolve(expanded)
    if (
        expression.className == CLASS &&
            (expression.arguments.size > 1 || expression.arguments.any { !it.simple })
    ) {
      throw ExpressionException(
          "a class literal accepts one bare class name; found `$expression`",
          sourceLocation =
              expression.arguments.firstOrNull { !it.simple }?.sourceLocation
                  ?: expression.arguments.getOrNull(1)?.sourceLocation
                  ?: expression.sourceLocation,
      )
    }
    cache[expression]?.let {
      return it
    }

    if (masterSource != null) {
      var requiresCombinedTable = false
      expression.visitDescendants { node ->
        if (node is Not || (node is ClassName && node in declarations)) {
          requiresCombinedTable = true
        }
        !requiresCombinedTable
      }
      if (!requiresCombinedTable) {
        return masterSource.resolve(expression).also { cache[expression] = it }
      }
    }
    expression.refinement?.conjuncts()?.filterIsInstance<Not>()?.forEach { refinement ->
      fun containsRefinement(candidate: Expression): Boolean =
          candidate.refinement != null || candidate.arguments.any(::containsRefinement)
      if (containsRefinement(refinement.excluded)) {
        throw ExpressionException(
            "`NOT` operand cannot contain a refinement: `$expression`",
            sourceLocation =
                refinement.excluded.refinement?.sourceLocation
                    ?: refinement.excluded.sourceLocation,
        )
      }
    }
    // Avoiding computeIfAbsent due to CME
    return try {
      getClass(expression.className)
          .specialize(expression.arguments, this)
          .inTable(this)
          .refine(expression.refinement)
          .also { cache[expression] = it }
    } catch (e: ExpressionException) {
      if (e.sourceLocation == null) e.sourceLocation = expression.sourceLocation
      throw e
    } catch (e: RuntimeException) {
      throw ExpressionException(
          "cannot resolve `$expression`: ${e.message}",
          e,
          expression.sourceLocation,
      )
    }
  }

  private lateinit var frozenClasses: MutableSet<Class>

  /**
   * Returns every included class after this table's structural universe is frozen; calling before
   * freezing violates
   * [rule T1-6](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  override fun allClasses(): Set<Class> {
    require(frozen) { "this class table must be frozen before its classes can be enumerated" }
    return frozenClasses
  }

  override fun allKnownClasses(): Set<Class> {
    require(frozen) { "this class table must be frozen before its classes can be enumerated" }
    if (masterSource == null) return frozenClasses
    return masterSource.allKnownClasses() +
        declarations.keys.mapTo(linkedSetOf()) { name -> getClass(name) }
  }

  // LOADING

  /** Returns the class whose stable [Class.className] is [name], loading it first if necessary. */
  internal fun load(name: ClassName): Class {
    if (!frozen) loadAll(listOf(name))
    return getClass(name)
  }

  /**
   * Loads every declaration, freezes the resulting master universe, and constructs every class's
   * base type and defaults. Invalid definitions fail here, including errors in otherwise lazy
   * dependency bounds and defaults. This satisfies the enumeration precondition in
   * [rule T1-6](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  public fun loadEverything(): ClassTable {
    knownClassNames.forEach(::loadSingle)
    val completed = freeze()
    validateBaseTypesAndDefaults(knownClassNames.mapTo(linkedSetOf(), ::getClass))
    validateNoOkSubscriptions()
    validateTransformKinds()
    return completed
  }

  private fun validateBaseTypesAndDefaults(classes: Set<Class>) {
    classes.forEach { klass ->
      inDefinition(klass.declaration) {
        klass.baseType
        klass.defaults
      }
    }
  }

  /** The classes this load is responsible for checking: a master's own, or a premise's delta. */
  private fun declaringClassesToValidate(): Set<Class> =
      if (masterSource == null) {
        allKnownClasses()
      } else {
        declarations.keys.mapTo(linkedSetOf(), ::getClass)
      }

  /**
   * Rejects a transform block whose kind this Catalog defines no handler for, per
   * [rule L8-2](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/pets-language-spec.md#8-transform-blocks).
   * One rewriting pass may leave another pass's kind in place, but a mark no pass will ever claim
   * is a mistake in the source.
   */
  private fun validateTransformKinds() {
    val known = transformHandlerFactories.keys
    declaringClassesToValidate().map(Class::declaration).forEach { declaration ->
      declaration.allNodes.forEach { root ->
        root.visitDescendants { node ->
          if (node is TransformNode<*> && node.transformKind !in known) {
            throw InvalidPetDefinitionException(
                "`${declaration.className}` uses undefined transform kind " +
                    "`${node.transformKind}` in `$node`; available kinds: ${known.sorted().joinToString().ifEmpty { "none" }}",
                sourceLocation =
                    node.sourceLocation
                        ?: root.sourceLocation
                        ?: declaration.className.sourceLocation,
            )
          }
          true
        }
      }
    }
  }

  /**
   * Rejects subscriptions rooted at `Ok` or a nominal supertype, which are statically forbidden.
   */
  private fun validateNoOkSubscriptions() {
    val okClass = getClass(OK)
    declaringClassesToValidate().forEach { declaringClass ->
      declaringClass.declaration.effects.forEach { effect ->
        val forbidden =
            effect.trigger
                .descendantsOfType<SubscribedTrigger>()
                .map {
                  when (it) {
                    is OnGainOf -> it.expression
                    is OnRemoveOf -> it.expression
                  }
                }
                .firstOrNull { expression ->
                  val triggerClass =
                      if (expression.className == THIS) declaringClass
                      else getClass(expression.className)
                  okClass.isSubtypeOf(triggerClass)
                }
        if (forbidden != null) {
          throw InvalidPetDefinitionException(
              "`${declaringClass.className}` effect `$effect` subscribes to `$forbidden`, " +
                  "whose root is `Ok` or a nominal supertype of `Ok`",
              sourceLocation = forbidden.sourceLocation ?: forbidden.className.sourceLocation,
          )
        }
      }
    }
  }

  private val queue = ArrayDeque<ClassName>()
  private val requestedBy = mutableMapOf<ClassName, ClassName?>()

  /** Loads [names] together, advancing their inclusion closure one complete frontier at a time. */
  private fun loadAll(names: Collection<ClassName>) {
    val inspected = mutableSetOf(COMPONENT, CLASS)
    val pending = mutableListOf<PendingSelection>()
    val interpreter =
        InhabitanceInterpreter(
            classIsUninhabited = { name ->
              if (masterSource == null) name !in includedClassNames else !isInhabited(name)
            },
            exactCount = { exactCount(it, this) },
        )
    enqueue(names, requestedByClass = null)
    while (queue.isNotEmpty()) {
      while (queue.isNotEmpty()) {
        val next = queue.removeFirst()
        checkAvailability(next, requestedBy.getValue(next))
        loadRelated(next, include = true)
      }
      // Include a whole frontier before evaluating its conditions, as in the closure definition.
      (includedClassNames - inspected).forEach { name ->
        inspected += name
        enqueue(selectionEdges(knownDeclaration(name), pending) - THIS, name)
      }
      val iterator = pending.iterator()
      while (iterator.hasNext()) {
        val edge = iterator.next()
        if (includedClassNames.containsAll(edge.names)) {
          iterator.remove()
        } else if (
            interpreter.triggerIsReachable(edge.trigger) &&
                edge.gates.none(interpreter::requirementIsFalse)
        ) {
          enqueue(edge.names, edge.requiredBy)
          iterator.remove()
        }
      }
    }
  }

  /**
   * Computes a game's inclusion closure within its completed structural namespace.
   *
   * Structural references and reachable constructive instructions include their required Classes.
   * Counts, requirements, and triggers alone do not, except that a positive lower bound in a Class
   * invariant includes the structural domain it counts. A constructive instruction beneath a
   * provably false gate or trigger is inert. The calculation repeats because each included Class
   * can make another edge reachable. A required Class locked behind an unselected Module makes the
   * premise broken rather than silently selecting that Module.
   */
  private fun includeAll(names: Collection<ClassName>) {
    require(masterSource != null && frozen) {
      "a game table must be structurally frozen before its inclusion closure is computed"
    }
    loadAll(names)
    specializeEffects()
  }

  private fun specializeEffects() {
    val countCache = mutableMapOf<Expression, Int?>()
    fun knownCount(expression: Expression): Int? {
      if (expression in countCache) return countCache[expression]
      return computePremiseCount(expression).also {
        countCache[expression] = it
      }
    }
    val interpreter =
        InhabitanceInterpreter(
            classIsUninhabited = { !isInhabited(it) },
            exactCount = ::knownCount,
        )
    premiseEffects =
        includedClassNames.map(::getClass).associateWith { klass ->
          klass.declaration.effects.mapNotNull { specializeEffect(it, interpreter) }
        }
  }

  private fun computePremiseCount(expression: Expression): Int? {
    val representedClass = expression.arguments.singleOrNull()
    if (
        expression.className == CLASS &&
            expression.refinement == null &&
            representedClass?.simple == true &&
            representedClass.className != THIS &&
            representedClass.typeVariableName == null
    ) {
      return allConcreteSubtypes(resolve(expression)).count()
    }
    return selectedModuleCount(expression, this)
  }

  private fun specializeEffect(
      effect: Effect,
      interpreter: InhabitanceInterpreter,
  ): Effect? {
    val trigger = specializeTrigger(effect.trigger, interpreter) ?: return null
    val instruction = specializeInstruction(effect.instruction, interpreter)
    if (trigger == effect.trigger && instruction == effect.instruction) return effect
    return effect.copy(trigger = trigger, instruction = instruction).also {
      it.sourceLocation = effect.sourceLocation
    }
  }

  private fun specializeTrigger(
      trigger: Trigger,
      interpreter: InhabitanceInterpreter,
  ): Trigger? =
      when (trigger) {
        is Trigger.BasicTrigger -> trigger
        is Or -> {
          val remaining = trigger.triggers.mapNotNull { specializeTrigger(it, interpreter) }
          when (remaining.size) {
            0 -> null
            1 -> remaining.single()
            else -> Or(remaining).also { it.sourceLocation = trigger.sourceLocation }
          }
        }
        is ByTrigger ->
            specializeTrigger(trigger.inner, interpreter)?.let {
              ByTrigger(it, trigger.by).also { result ->
                result.sourceLocation = trigger.sourceLocation
              }
            }
        is IfTrigger -> {
          val inner = specializeTrigger(trigger.inner, interpreter) ?: return null
          when (val condition = interpreter.simplifyRequirement(trigger.condition)) {
            SimplifiedRequirement.Always -> inner
            SimplifiedRequirement.Never -> null
            is SimplifiedRequirement.Conditional ->
                IfTrigger(inner, condition.requirement).also {
                  it.sourceLocation = trigger.sourceLocation
                }
          }
        }
        is XTrigger,
        is Transform -> trigger
      }

  private fun specializeInstruction(
      instruction: InstructionTree,
      interpreter: InhabitanceInterpreter,
  ): InstructionTree =
      object : PetTransformer() {
            override fun transformNode(node: PetNode): PetNode =
                when (node) {
                  is Gated -> {
                    when (val gate = interpreter.simplifyRequirement(node.gate)) {
                      SimplifiedRequirement.Always -> transformInstructionTree(node.inner)
                      // A false gate rejects its operation when reached. Keeping it also preserves
                      // lazy bodies such as an empty EACH or zero-valued PER.
                      SimplifiedRequirement.Never -> node
                      is SimplifiedRequirement.Conditional ->
                          Gated(gate.requirement, transformInstructionTree(node.inner)).also {
                            it.sourceLocation = node.sourceLocation
                          }
                    }
                  }
                  else -> transformChildren(node)
                }
          }
          .transformInstructionTree(instruction)

  private fun enqueue(names: Collection<ClassName>, requestedByClass: ClassName?) {
    (names - includedClassNames - queue).forEach { name ->
      requestedBy[name] = requestedByClass
      queue += name
    }
  }

  private fun includeClass(name: ClassName) {
    if (includedClassNames.add(name)) {
      if (frozen) frozenClasses += getClass(name)
      invalidateInclusionCaches()
    }
  }

  internal fun loadRelated(next: ClassName, include: Boolean): Class {
    if (masterSource != null && next !in declarations) {
      val klass = masterSource.getClass(next)
      if (include) includeClass(next)
      return klass
    }
    if (next in loadedClasses) {
      return (loadedClasses[next] ?: throw inheritanceCycle(next)).also {
        if (include) includeClass(next)
      }
    }
    val declaration = knownDeclaration(next)
    return inDefinition(declaration) {
      validateClassNames(declaration)
      validateNoEffectCreatesClass(declaration)
      construct(declaration, include).also { if (include) includeClass(next) }
    }
  }

  private fun validateNoEffectCreatesClass(declaration: ClassDeclaration) {
    val change =
        declaration.effects
            .flatMap { effect -> effect.instruction.descendantsOfType<Change>() }
            .firstOrNull { it.gaining?.className == CLASS } ?: return
    throw InvalidPetDefinitionException(
        "class representatives cannot be gained by an effect: `$change`",
        sourceLocation = change.gaining?.sourceLocation,
    )
  }

  /**
   * Rejects every name this declaration writes that the catalog never declares, enforcing
   * [rule T1-7](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity)
   * where the declaration that spelled it can still be named. Only the name is decided here;
   * whether an argument fits its bound depends on classes this one may be loaded ahead of.
   */
  private fun validateClassNames(declaration: ClassDeclaration) {
    declaration.allNodes.forEach { node ->
      node.visitDescendants {
        val name = it as? ClassName
        if (name != null && name != THIS && name !in knownClassNames) {
          throw InvalidPetDefinitionException(
              if (name.sourceLocation == null)
                  "`${declaration.className}` requires undeclared class `$name`"
              else
                  "`${declaration.className}` names undeclared class `$name`; declare it or correct the name",
              sourceLocation = name.sourceLocation,
          )
        }
        true
      }
    }
  }

  /** A constructive reference awaiting its complete trigger and enclosing instruction gates. */
  private class PendingSelection(
      val requiredBy: ClassName,
      val names: Set<ClassName>,
      val trigger: Trigger,
      val gates: List<Requirement>,
  )

  /** Reads structural references once; constructive references remain pending until reachable. */
  private fun selectionEdges(
      declaration: ClassDeclaration,
      pending: MutableList<PendingSelection>,
  ): Set<ClassName> = buildSet {
    fun collectStructural(expression: Expression) {
      add(expression.className)
      expression.arguments.forEach(::collectStructural)
    }

    fun collectRequiredInhabitants(requirement: Requirement) {
      when (requirement) {
        is Requirement.Counting if
            requirement.range.first > 0 && requirement.metric is Metric.Count
         -> collectStructural(requirement.metric.expression)
        is Requirement.Counting -> Unit
        is Requirement.And -> requirement.requirements.forEach(::collectRequiredInhabitants)
        is Requirement.Or -> requirement.requirements.forEach(::collectRequiredInhabitants)
        is Requirement.Eval,
        is Requirement.Transform -> Unit
      }
    }

    fun collectInstruction(tree: InstructionTree, trigger: Trigger, gates: List<Requirement>) {
      when (tree) {
        is Gain,
        is Transmute -> {
          val gaining = checkNotNull((tree as Change).gaining)
          val names = linkedSetOf<ClassName>()
          fun collect(expression: Expression) {
            if (expression.className != THIS) names += expression.className
            expression.arguments.forEach(::collect)
          }
          collect(gaining)
          if (names.isNotEmpty()) {
            pending += PendingSelection(declaration.className, names, trigger, gates)
          }
        }
        is Gated -> collectInstruction(tree.inner, trigger, gates + tree.gate)
        else ->
            tree.childNodes().filterIsInstance<InstructionTree>().forEach {
              collectInstruction(it, trigger, gates)
            }
      }
    }

    declaration.supertypes.forEach(::collectStructural)
    declaration.dependencies.forEach(::collectStructural)
    declaration.defaultsDeclaration.allNodes
        .filterIsInstance<Expression>()
        .forEach(::collectStructural)
    declaration.defaultsDeclaration.forClass?.let(::add)
    declaration.invariants.forEach(::collectRequiredInhabitants)
    declaration.effects.forEach { collectInstruction(it.instruction, it.trigger, emptyList()) }
    declaration.allNodes
        .flatMap { it.descendantsOfType<ClassName>() }
        .filter { it != THIS && it in knownClassNames && knownDeclaration(it).customMetric }
        .forEach(::add)
    declaration.extraNodes.forEach { node -> node.descendantsOfType<ClassName>().forEach(::add) }
  }

  private fun loadSingle(name: ClassName): Class =
      findClass(name)?.also { includeClass(name) } ?: loadRelated(name, include = true)

  private var constructionDepth = 0

  // All classes are created here (aside from Component and Class, at top).
  private fun construct(source: ClassDeclaration, includeRelated: Boolean = true): Class {
    check(masterSource == null || source.className in declarations) {
      "a game table may construct only premise classes"
    }
    require(!frozen) { "class table is already frozen" }
    if (constructionDepth >= 128) {
      throw ResourceLimitException(
          "class construction exceeds 128 levels at `${source.className}`",
          sourceLocation = source.className.sourceLocation,
      )
    }
    val decl = source.also(validateDeclaration)

    fun store(c: Class?) {
      loadedClasses[decl.className] = c
    }
    store(null) // to detect reentrancy
    constructionDepth++
    try {
      val klass = Class(decl, this, includeRelated)
      validateCustomInheritance(klass)
      store(klass)
      return klass
    } catch (e: Throwable) {
      loadedClasses.remove(decl.className)
      throw e
    } finally {
      constructionDepth--
    }
  }

  private fun inheritanceCycle(name: ClassName): InvalidPetDefinitionException {
    val path = loadedClasses.filterValues { it == null }.keys.toList()
    val cycle = path.dropWhile { it != name } + name
    val previous = path.lastOrNull()?.let(::knownDeclaration)
    val occurrence = previous?.supertypes?.firstOrNull { it.className == name }
    return InvalidPetDefinitionException(
        "inheritance cycle: ${cycle.joinToString(" -> ") { "`$it`" }}; a class cannot extend itself",
        sourceLocation = occurrence?.sourceLocation ?: name.sourceLocation,
    )
  }

  /** Lazy type construction must still report failures as errors in the owning declaration. */
  internal inline fun <T> inDefinition(declaration: ClassDeclaration, block: () -> T): T =
      try {
        block()
      } catch (e: ExpressionException) {
        throw InvalidPetDefinitionException(
            "invalid definition for `${declaration.className}`: ${e.detail}",
            e,
            e.sourceLocation ?: declaration.className.sourceLocation,
        )
      } catch (e: DomainException) {
        if (e.sourceLocation == null) e.sourceLocation = declaration.className.sourceLocation
        throw e
      }

  private fun validateCustomInheritance(klass: Class) {
    if (!klass.declaration.customMetric) return

    val inheritedEffects = klass.properSuperclasses().filter { it.declaration.effects.isNotEmpty() }
    val inheritedInvariants =
        klass.properSuperclasses().filter { it.declaration.invariants.isNotEmpty() }
    fun hasInstructionQuantifier(defaults: DefaultsDeclaration): Boolean =
        defaults.universal.quantifier != null ||
            defaults.gainOnly.quantifier != null ||
            defaults.removeOnly.quantifier != null

    val inheritedDefaults =
        klass.properSuperclasses().filter {
          it.className != COMPONENT && hasInstructionQuantifier(it.declaration.defaultsDeclaration)
        }
    val problems = buildList {
      if (inheritedEffects.isNotEmpty()) {
        add("effects from " + inheritedEffects.joinToString { "${it.className}" })
      }
      if (inheritedInvariants.isNotEmpty()) {
        add("invariants from " + inheritedInvariants.joinToString { "${it.className}" })
      }
      if (inheritedDefaults.isNotEmpty()) {
        add("instruction defaults from " + inheritedDefaults.joinToString { "${it.className}" })
      }
    }
    if (problems.isNotEmpty()) {
      throw InvalidPetDefinitionException(
          "`${klass.className}` cannot inherit Pets behavior as a custom metric: " +
              problems.joinToString()
      )
    }
  }

  private var frozen: Boolean = false

  private var allSubclassesByClass: Map<Class, Set<Class>>? = null
  private var directSubclassesByClass: Map<Class, Set<Class>>? = null

  internal override fun allSubclassesOf(klass: Class): Set<Class> {
    require(frozen) {
      "this class table must be frozen before the subclasses of `$klass` can be enumerated"
    }
    return checkNotNull(allSubclassesByClass).getValue(klass)
  }

  internal override fun directSubclassesOf(klass: Class): Set<Class> {
    require(frozen) {
      "this class table must be frozen before the subclasses of `$klass` can be enumerated"
    }
    return checkNotNull(directSubclassesByClass)[klass] ?: emptySet()
  }

  private fun freeze(): ClassTable {
    require(!frozen)
    if (masterSource != null) {
      declarations.values.forEach { declaration ->
        if (declaration.className !in loadedClasses) {
          inDefinition(declaration) {
            validateClassNames(declaration)
            validateNoEffectCreatesClass(declaration)
            construct(declaration, includeRelated = false)
          }
        }
      }
      val premiseClasses =
          declarations.keys.mapTo(linkedSetOf()) { name ->
            checkNotNull(loadedClasses[name])
          }
      allSubclassesByClass = premiseClasses.associateWith { klass ->
        premiseClasses.filterTo(linkedSetOf()) { candidate -> candidate.isSubtypeOf(klass) }
      }
      directSubclassesByClass = premiseClasses.associateWith { klass ->
        premiseClasses.filterTo(linkedSetOf()) { candidate ->
          klass in candidate.directSuperclasses
        }
      }
      frozenClasses = includedClassNames.mapTo(linkedSetOf(), ::getClass)
      frozen = true
      validateBaseTypesAndDefaults(premiseClasses)
      return this
    }
    knownClassNames.forEach { name ->
      if (name !in loadedClasses) construct(knownDeclaration(name))
    }

    val knownClasses = loadedClasses.values.map { checkNotNull(it) }
    val knownProperSubclasses = mutableMapOf<Class, MutableSet<Class>>()
    knownClasses.forEach { subclass ->
      subclass.allSuperclasses().forEach { superclass ->
        if (superclass !== subclass) {
          knownProperSubclasses.getOrPut(superclass, ::linkedSetOf).add(subclass)
        }
      }
    }
    val bitBearingSuperclasses = knownClasses.flatMap(Class::directSuperclasses).distinct()
    val superclassBits =
        bitBearingSuperclasses
            .sortedWith(
                compareByDescending<Class> { knownProperSubclasses[it]?.size ?: 0 }
                    .thenBy(Class::className)
            )
            .withIndex()
            .associate { (index, klass) -> klass to index }
    knownClasses.forEach { it.initializeSubclassBits(superclassBits) }

    allSubclassesByClass = knownClasses.associateWith { klass ->
      knownProperSubclasses[klass].orEmpty() + klass
    }

    val directSubclasses = mutableMapOf<Class, MutableSet<Class>>()
    knownClasses.forEach { subclass ->
      subclass.directSuperclasses.forEach { superclass ->
        directSubclasses.getOrPut(superclass, ::linkedSetOf).add(subclass)
      }
    }
    directSubclassesByClass = directSubclasses.mapValues { (_, subclasses) -> subclasses.toSet() }

    frozenClasses = knownClasses.toCollection(linkedSetOf())
    frozen = true
    return this
  }

  /**
   * Every included class name after this table's structural universe is frozen; calling before
   * freezing violates
   * [rule T1-6](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  public override val allClassNames: Set<ClassName>
    get() {
      require(frozen) { "this class table must be frozen before its classes can be enumerated" }
      return if (masterSource == null) loadedClasses.keys else includedClassNames
    }

  /**
   * Returns a diagnostic identity for this universe; semantic identity is the object boundary
   * specified by
   * [rules T1-1 and T1-2](https://github.com/MartianZoo/solarnet/blob/main/pets/docs/type-system-spec.md#1-universes-and-identity).
   */
  override fun toString(): String = "loader$id"

  private fun knownDeclaration(name: ClassName): ClassDeclaration =
      declarations[name]
          ?: masterSource?.getClass(name)?.declaration
          ?: throw ExpressionException("no class named `$name` in the current game")

  private val id = nextId++

  public companion object {
    private var nextId: Int = 0

    /**
     * Compiles and validates [premiseTable]'s declarations, freezes the combined namespace, and
     * returns the completed inclusion closure of [roots]. Master Classes and Types are reused. The
     * returned view is immutable; game-specific configuration validation belongs to its caller.
     *
     * [checkAvailability] may reject a required Class and receives the Class that required it, or
     * null for a root. [exactCount] supplies configuration counts used only while deciding which
     * declarations can become reachable; its table's inclusion set is still being computed.
     * [exactCount] returns null for unknown counts. After the closure is complete, structurally
     * installed `Class<T>` counts and caller-supplied [selectedModuleCount] facts specialize
     * executable effects before any World is built. [selectedModuleCount] must return the exact
     * selected count for a supported simple Module expression and null for every non-Module or
     * unsupported expression; it describes the completed configuration rather than transient
     * bootstrap state.
     */
    public fun forPremise(
        premiseTable: PremiseClassTable,
        roots: Collection<ClassName>,
        checkAvailability: (ClassName, ClassName?) -> Unit = { _, _ -> },
        exactCount: (Expression, ClassTable) -> Int? = { _, _ -> null },
        selectedModuleCount: (Expression, ClassTable) -> Int? = { _, _ -> null },
    ): ClassTable {
      val masterTable = premiseTable.master
      require(masterTable.masterTable === masterTable) {
        "catalog class table is not a master table"
      }
      return ClassLoader(
              premiseTable.declarations,
              masterTable.transformHandlerFactories,
              {},
              masterTable,
              checkAvailability,
              exactCount,
              selectedModuleCount,
          )
          .apply {
            freeze()
            validateNoOkSubscriptions()
            validateTransformKinds()
            includeAll(roots)
          }
    }
  }
}
